export function createIndianDictionary(dict: Record<string, string>): Record<string, string> {
  const normalized: Record<string, string> = {};
  for (const [k, v] of Object.entries(dict)) {
    normalized[k] = v;
    normalized[k.toLowerCase()] = v;
    normalized[k.trim()] = v;
  }
  return normalized;
}

